import React, { useEffect } from 'react'
import { Editor, Range, Element, Node, NodeEntry, Ancestor, Descendant, Path } from 'slate'
import orderBy from 'lodash/orderBy'

import ElementComponent from './element'
import TextComponent from './text'
import { ReactEditor } from '..'
import { useSlateStatic } from '../hooks/use-slate-static'
import { useDecorate } from '../hooks/use-decorate'
import { IndexContext } from '../hooks/use-index'
import { KEY_TO_INDEX, KEY_TO_PARENT, NODE_TO_INDEX, NODE_TO_PARENT } from '../utils/weak-maps'
import { RenderElementProps, RenderLeafProps } from './editable'

/**
 * Children.
 */

const Children = (props: {
  decorations: Range[]
  node: Ancestor
  renderElement?: (props: RenderElementProps) => JSX.Element
  renderLeaf?: (props: RenderLeafProps) => JSX.Element
  selection: Range | null
}) => {
  const { decorations, renderElement, renderLeaf, selection } = props
  let { node } = props
  const editor = useSlateStatic()
  const { decorate, useDecorateState } = useDecorate()
  const decorateState = useDecorateState && useDecorateState()
  const nodeKey = ReactEditor.findKey(editor, node)
  let path = ReactEditor.findPath(editor, node)
  const decorateStateRef = React.useRef({})
  if (decorateState) {
    useEffect(() => {
      return () => {
        if (decorateStateRef.current.pathRef) {
          decorateStateRef.current.pathRef.unref()
          delete decorateStateRef.current.pathRef
        }
      }
    }, [])
    // decorateState with the element key changes when we need re-run decorate by some external condition.
    const state = decorateState[nodeKey.id]
    const isDirty = !editor.isFlushed()
    if (decorateStateRef.current.state !== state || isDirty) {
      if (
        // decorateStateRef.current.pathRef && !Path.isEqual(decorateStateRef.current.pathRef.current, path) ||
        editor.operations.length > 0 &&
        editor.operations.some(op => op.type !== 'set_selection')
      ) {
        let newNode
        try {
          newNode = Node.get(editor, path)
        } catch (err) {
        }
        if (newNode !== node) {
          // XXX: the current node was removed, but probably decorateState triggered re-render here, so we need skip it.
          // the real problem is the 'path' is not correct, since the node updated but the render in element did not happen before this.
          // A. now we either not render it (what if it is not fully re-renderd after this temp render?)
          // B. or we return the last cached result (have to cache every node, it's huge?)
          // C. or we need figure out the correct path currently it is. but how? and all sub-children?
          // XXX: find a node in the whole editor is expensive.
          //      maybe just the parent is no longer in the tree, a new parent replaced it, with new children include current node
          //      in this case, all we have is parent path, then try to find current node in the new parent's children.
          //      but what if the node replaced is some root close node, for parent node, without pathRef, we are not easy to relocate them
          //      pathRef is good, but keep it for all children, is also expensive.
          // XXX: what if, the decorateState is not empty, then we keep the pathRef for current node?

          if (decorateStateRef.current.pathRef?.current) {
            if (Path.equals(decorateStateRef.current.pathRef.current, path)) {
              console.log('Children: node updated:', path, node, '=>', newNode, editor.operations, nodeKey.id, state, isDirty)
              node = newNode
            } else {
              console.log('Children: use updated path for node:', node, path, '=>', decorateStateRef.current.pathRef.current, editor.operations, nodeKey.id, state, isDirty)
              path = decorateStateRef.current.pathRef.current
              node = Node.get(editor, path)
            }
          } else {
            console.log('Children: skip decorateState update for removed node:', node, path, editor.operations, nodeKey.id, state, isDirty)
            return null
          }
        }
      }

      decorateStateRef.current.state = state

      if (state && !decorateStateRef.current.pathRef) {
        decorateStateRef.current.pathRef = Editor.pathRef(editor, path)
      } else if (!state && decorateStateRef.current.pathRef) {
        decorateStateRef.current.pathRef.unref()
        delete decorateStateRef.current.pathRef
      }
    }
  }
  const children = []
  const isLeafBlock =
    Element.isElement(node) &&
    !editor.isInline(node) &&
    Editor.hasInlines(editor, node)

  let nodeChildren
  if (isLeafBlock || !node.childrenOrderedBy) {
    nodeChildren = node.children.map((child, idx) => [child, idx])
  } else {
    let sortFields = node.childrenOrderedBy
    let sortOrders
    if (
      sortFields.length === 2 &&
      (['asc', 'desc'].includes(sortFields[1]) ||
        (Array.isArray(sortFields[1]) &&
          ['asc', 'desc'].includes(sortFields[1][0])))
    ) {
      ;[sortFields, sortOrders] = sortFields
      if (typeof sortFields === 'string') {
        sortFields = [sortFields]
      }
      sortFields = sortFields.map(field => editor.sortIterateFunctions && editor.sortIterateFunctions[field] || field)
    }
    nodeChildren = orderBy(
      node.children,
      sortFields,
      sortOrders as 'asc' | 'desc' | ('asc' | 'desc')[]
    ).map((child) => [child, node.children.indexOf(child)])
  }

  let idx = 0
  for (const child of nodeChildren) {
    const n = child[0] as Descendant
    const i = child[1] as number
    const key = ReactEditor.findKey(editor, n)
    KEY_TO_INDEX.set(key, i)
    KEY_TO_PARENT.set(key, nodeKey)
    NODE_TO_INDEX.set(n, i)
    NODE_TO_PARENT.set(n, node)
    const p = path.concat(i)
    const range = Editor.range(editor, p)
    const sel = selection && Range.intersection(range, selection)
    const ds = decorate([n, p])

    for (const dec of decorations) {
      const d = Range.intersection(dec, range)

      if (d) {
        ds.push(d)
      }
    }

    if (Element.isElement(n)) {
      if (node.droppable || ['ul', 'ol'].includes(node.type)) {
        children.push(
          <IndexContext.Provider key={key.id} value={idx}>
            <ElementComponent
              decorations={ds}
              element={n}
              key={key.id}
              renderElement={renderElement}
              renderLeaf={renderLeaf}
              selection={sel}
            />
          </IndexContext.Provider>
        )
      } else {
        children.push(
          <ElementComponent
            decorations={ds}
            element={n}
            key={key.id}
            renderElement={renderElement}
            renderLeaf={renderLeaf}
            selection={sel}
          />
        )
      }
    } else {
      children.push(
        <TextComponent
          decorations={ds}
          key={key.id}
          isLast={isLeafBlock && i === nodeChildren.length - 1}
          parent={node}
          renderLeaf={renderLeaf}
          text={n}
        />
      )
    }

    idx++
  }

  return <React.Fragment>{children}</React.Fragment>
}

export default Children
